const data = JSON.parse($input.first().json.output);


// =====================================================
// HELPERS
// =====================================================

function escapeHtml(value) {
  if (value === null || value === undefined) return "";

  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}


function normalizeList(value) {

  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map(item => String(item).trim())
      .filter(Boolean);
  }

  return String(value)
    .split(/[•\n]/)
    .map(item => item
      .replace(/^[-*]\s*/, "")
      .trim()
    )
    .filter(Boolean);
}


// =====================================================
// DATA
// =====================================================

const score = Math.max(
  0,
  Math.min(
    100,
    Number(data.readiness_score) || 0
  )
);


const currentSkills =
  normalizeList(data.current_skills);


const missingSkills =
  normalizeList(data.missing_skills);


const roadmap =
  normalizeList(data.learning_roadmap);


const recommendation =
  escapeHtml(data.recommendation);


// =====================================================
// SCORE STATUS
// =====================================================

let scoreColor = "#dc2626";
let scoreLight = "#fef2f2";
let scoreBorder = "#fecaca";
let status = "Needs Improvement";
let statusIcon = "⚠️";

if (score >= 80) {

  scoreColor = "#16a34a";
  scoreLight = "#f0fdf4";
  scoreBorder = "#bbf7d0";

  status = "Job Ready";
  statusIcon = "🚀";

} else if (score >= 60) {

  scoreColor = "#d97706";
  scoreLight = "#fffbeb";
  scoreBorder = "#fde68a";

  status = "Almost Ready";
  statusIcon = "📈";
}


// =====================================================
// SKILL CHIPS
// =====================================================

function createSkillChips(items) {

  if (!items.length) {

    return `
      <span style="
        color:#64748b;
        font-size:13px;
      ">
        No skills identified.
      </span>
    `;

  }

  return items.map(skill => `

    <span style="
      display:inline-block;
      background:#ffffff;
      border:1px solid #dbe3ec;
      border-radius:18px;
      padding:7px 12px;
      margin:3px 3px 3px 0;
      color:#334155;
      font-size:12px;
      font-weight:500;
    ">
      ${escapeHtml(skill)}
    </span>

  `).join("");

}


// =====================================================
// ROADMAP
// =====================================================

function createRoadmap(items) {

  if (!items.length) {

    return `
      <p style="
        margin:0;
        color:#64748b;
        font-size:13px;
      ">
        No roadmap available.
      </p>
    `;

  }

  return items.map((item, index) => `

    <table
      width="100%"
      cellpadding="0"
      cellspacing="0"
      border="0"
      style="margin-bottom:14px;"
    >

      <tr>

        <td
          width="42"
          valign="top"
          style="padding-right:12px;"
        >

          <div style="
            width:34px;
            height:34px;
            line-height:34px;
            text-align:center;
            background:#2563eb;
            color:#ffffff;
            border-radius:50%;
            font-size:12px;
            font-weight:bold;
          ">
            ${String(index + 1).padStart(2, "0")}
          </div>

        </td>


        <td
          valign="middle"
          style="
            padding:5px 0;
            color:#334155;
            font-size:13px;
            line-height:1.6;
          "
        >

          ${escapeHtml(item)}

        </td>

      </tr>

    </table>

  `).join("");

}


// =====================================================
// EMAIL
// =====================================================

return [{
